public with sharing class ContactTriggerHandler {

    // Cached Accounts for this transaction, so we never query the same Accounts twice.
    private static Map<Id, Account> accountCache = new Map<Id, Account>();

    public static void handleBeforeInsert(List<Contact> newContacts) {
        populateAccountCache(newContacts);
        applyBeforeLogic(newContacts, true);
    }

    public static void handleBeforeUpdate(List<Contact> newContacts) {
        populateAccountCache(newContacts);
        applyBeforeLogic(newContacts, false);
    }

    public static void handleAfterInsert(List<Contact> newContacts) {
        Set<Id> candidateAccountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                candidateAccountIds.add(c.AccountId);
            }
        }
        if (candidateAccountIds.isEmpty()) {
            return;
        }

        // Reuse cached Accounts when possible; query only the ones we have not seen yet.
        Set<Id> toQuery = new Set<Id>();
        for (Id accId : candidateAccountIds) {
            if (!accountCache.containsKey(accId)) {
                toQuery.add(accId);
            }
        }
        if (!toQuery.isEmpty()) {
            accountCache.putAll([
                SELECT Id, Phone, BillingCountry, AccountSource
                FROM Account
                WHERE Id IN :toQuery
            ]);
        }

        // First qualifying contact (in trigger order) wins for each Account.
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account cached = accountCache.get(c.AccountId);
            if (cached == null || String.isNotBlank(cached.Phone)) {
                continue;
            }
            if (!accountsToUpdate.containsKey(c.AccountId)) {
                Account toUpdate = new Account(Id = c.AccountId, Phone = c.Phone);
                accountsToUpdate.put(c.AccountId, toUpdate);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values(); // single DML statement
            // Refresh the cache so later logic in this transaction sees the new Phone.
            for (Account updated : accountsToUpdate.values()) {
                accountCache.get(updated.Id).Phone = updated.Phone;
            }
        }
    }

    private static void populateAccountCache(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && !accountCache.containsKey(c.AccountId)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }
        accountCache.putAll([
            SELECT Id, Phone, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);
    }

    private static void applyBeforeLogic(List<Contact> newContacts, Boolean isInsert) {
        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountCache.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }
}
```

Notes on how the budget is met:

- **SOQL:** `populateAccountCache` runs one bulk query in the before context; `handleAfterInsert` normally finds every Account already cached (same transaction), so no additional query is needed. Even in the worst case (cache miss in after), the total is 2 SOQL queries.
- **DML:** Account Phone updates are collected into a single list — one `update` statement regardless of batch size.
- **First-contact-wins:** `handleAfterInsert` iterates `Trigger.new` in order and only records the first blank-Phone Account per `AccountId`, matching the original behaviour.
- **Behaviour preserved:** MailingCountry/LeadSource defaults on before insert/update, and Phone propagation on after insert, are identical to the legacy trigger — just bulk-safe now.

