/**
 * Queueable job that re-rates accounts in batches of 200 per execution,
 * chaining itself until all supplied Account Ids have been processed.
 */
public with sharing class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : accountIds;
    }

    /**
     * Enqueues the first job in the chain and returns its AsyncApexJob Id.
     * Returns null when the supplied list is null or empty.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Determine this execution's slice: at most the first 200 Ids.
        Integer processCount = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> currentBatch = accountIds.subList(0, processCount);

        // One SOQL query per execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentBatch
        ];

        // One DML statement per execution.
        List<Account> toUpdate = new List<Account>();
        for (Account acct : accounts) {
            String newRating;
            if (acct.AnnualRevenue != null && acct.AnnualRevenue >= 1000000) {
                newRating = 'Hot';
            } else if (acct.AnnualRevenue != null && acct.AnnualRevenue >= 100000) {
                newRating = 'Warm';
            } else {
                newRating = 'Cold';
            }
            acct.Rating = newRating;
            toUpdate.add(acct);
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }

        // Chain the remainder, if any. Chaining is never skipped in tests;
        // on current releases chained Queueables (and their chain depth) are
        // fully supported inside Apex tests, so the whole chain runs between
        // Test.startTest() and Test.stopTest().
        if (processCount < accountIds.size()) {
            List<Id> remaining = accountIds.subList(processCount, accountIds.size());
            System.enqueueJob(new AccountScoringJob(new List<Id>(remaining)));
        }
    }
}
