/**
 * Schedulable job that purges old FB_Integration_Log__c records.
 *
 * Retention rules:
 *  - ERROR logs are kept for 180 days.
 *  - All other logs (including blank Level__c) are kept for 30 days.
 */
public with sharing class LogPurgeJob implements Schedulable {

    private static final Integer NON_ERROR_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** No-argument constructor required for scheduling. */
    public LogPurgeJob() {}

    public void execute(SchedulableContext ctx) {
        purgeOldLogs();
    }

    /**
     * Deletes logs older than their retention window, in bulk-safe batches.
     */
    public static void purgeOldLogs() {
        delete [SELECT Id FROM FB_Integration_Log__c
                WHERE (CreatedDate < :System.now().addDays(-NON_ERROR_RETENTION_DAYS)
                       AND (Level__c = null OR (Level__c != 'ERROR')))
                   OR (Level__c = 'ERROR'
                       AND CreatedDate < :System.now().addDays(-ERROR_RETENTION_DAYS))];
    }

    /**
     * Schedules the job to run daily at 02:00 under the name 'Log purge (nightly)'.
     *
     * @return The CronTrigger Id returned by System.schedule.
     */
    public static Id scheduleNightly() {
        // Seconds Minutes Hours Day_of_Month Month Day_of_Week Optional_Year
        String cron = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cron, new LogPurgeJob());
    }
}
