@IsTest
private class OpportunitiesServiceTest {

    private static final Decimal VALID_PERCENTAGE = 20;

    private static Id fakeOppId(Integer index) {
        return fflib_IDGenerator.generate(Opportunity.SObjectType, index);
    }

    @IsTest
    static void applyDiscountsAppliesDiscountViaDomainAndCommitsUnitOfWork() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        IOpportunities domainMock = (IOpportunities) mocks.mock(IOpportunities.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        Application.Domain.setMock(Opportunity.SObjectType, (Opportunities) domainMock);
        Application.UnitOfWork.setMock(uowMock);

        Set<Id> opportunityIds = new Set<Id>{
            fakeOppId(1),
            fakeOppId(2)
        };

        List<Opportunity> selectedOpps = new List<Opportunity>{
            new Opportunity(Id = fakeOppId(1), Amount = 100),
            new Opportunity(Id = fakeOppId(2), Amount = 250)
        };
        mocks.when(selectorMock.selectById(opportunityIds)).thenReturn(selectedOpps);

        Test.startTest();
        OpportunitiesService.applyDiscounts(opportunityIds, VALID_PERCENTAGE);
        Test.stopTest();

        // The selector must be used with the given ids, exactly once.
        mocks.verify(selectorMock, mocks.times(1)).selectById(opportunityIds);

        // The domain must receive the percentage unchanged and the
        // unit of work from Application.UnitOfWork, and be called once.
        mocks.verify(domainMock, mocks.times(1)).applyDiscount(VALID_PERCENTAGE, uowMock);

        // The unit of work must be committed once, after applyDiscount.
        mocks.startOrdering();
        mocks.verify(domainMock, mocks.times(1)).applyDiscount(VALID_PERCENTAGE, uowMock);
        mocks.verify(uowMock, mocks.times(1)).commitWork();
        mocks.stopOrdering();

        mocks.verify(uowMock, mocks.times(1)).commitWork();
    }

    @IsTest
    static void applyDiscountsAcceptsBoundaryPercentages() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        IOpportunities domainMock = (IOpportunities) mocks.mock(IOpportunities.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        Application.Domain.setMock(Opportunity.SObjectType, (Opportunities) domainMock);
        Application.UnitOfWork.setMock(uowMock);

        Set<Id> opportunityIds = new Set<Id>{ fakeOppId(1) };
        mocks.when(selectorMock.selectById(opportunityIds))
            .thenReturn(new List<Opportunity>{ new Opportunity(Id = fakeOppId(1)) });

        Test.startTest();
        OpportunitiesService.applyDiscounts(opportunityIds, 50);
        OpportunitiesService.applyDiscounts(opportunityIds, 0.01);
        Test.stopTest();

        mocks.verify(selectorMock, mocks.times(2)).selectById(opportunityIds);
        mocks.verify(domainMock, mocks.times(1)).applyDiscount(50, uowMock);
        mocks.verify(domainMock, mocks.times(1)).applyDiscount(0.01, uowMock);
        mocks.verify(uowMock, mocks.times(2)).commitWork();
    }

    @IsTest
    static void applyDiscountsThrowsForInvalidPercentages() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        IOpportunities domainMock = (IOpportunities) mocks.mock(IOpportunities.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        Application.Domain.setMock(Opportunity.SObjectType, (Opportunities) domainMock);
        Application.UnitOfWork.setMock(uowMock);

        Set<Id> opportunityIds = new Set<Id>{ fakeOppId(1) };

        List<Decimal> invalidPercentages = new List<Decimal>{
            null,
            0,
            -1,
            -100,
            50.01,
            51,
            100
        };

        for (Decimal invalidPercentage : invalidPercentages) {
            Boolean exceptionThrown = false;
            try {
                OpportunitiesService.applyDiscounts(opportunityIds, invalidPercentage);
            } catch (OpportunitiesService.OpportunitiesServiceException e) {
                exceptionThrown = true;
            }
            System.assertEquals(
                true,
                exceptionThrown,
                'Expected exception for discountPercentage: ' + invalidPercentage
            );
        }

        // Invalid input must not touch the selector, the domain or the unit of work.
        mocks.verify(selectorMock, mocks.never()).selectById(opportunityIds);
        mocks.verify(domainMock, mocks.never()).applyDiscount(
            fflib_Match.anyDecimal(),
            (fflib_ISObjectUnitOfWork) fflib_Match.anyObject()
        );
        mocks.verify(uowMock, mocks.never()).commitWork();
    }

    @IsTest
    static void applyDiscountsDoesNothingForNullOrEmptyIds() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        IOpportunities domainMock = (IOpportunities) mocks.mock(IOpportunities.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        Application.Domain.setMock(Opportunity.SObjectType, (Opportunities) domainMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        OpportunitiesService.applyDiscounts(null, VALID_PERCENTAGE);
        OpportunitiesService.applyDiscounts(new Set<Id>(), VALID_PERCENTAGE);
        Test.stopTest();

        // Nothing may be selected, applied or committed.
        mocks.verify(selectorMock, mocks.never()).selectById((Set<Id>) fflib_Match.anyObject());
        mocks.verify(domainMock, mocks.never()).applyDiscount(
            fflib_Match.anyDecimal(),
            (fflib_ISObjectUnitOfWork) fflib_Match.anyObject()
        );
        mocks.verify(uowMock, mocks.never()).commitWork();
    }
}
```

Notes on the design:

- **Pure unit test**: every collaborator (selector, domain, unit of work) is an ApexMocks mock injected via `Application.Selector.setMock`, `Application.Domain.setMock` and `Application.UnitOfWork.setMock`; record ids come from `fflib_IDGenerator`, so there is no DML and no SOQL anywhere.
- **Domain is mocked, not exercised**: `applyDiscount` is verified as a call on the `IOpportunities` mock; the real `Opportunities` domain logic is covered by its own tests.
- **Validation contract**: for `null`, `0`, negative, and >50 percentages the exception is asserted, and `never()` verifications prove the selector, domain and unit of work were untouched.
- **Happy path**: the selector is called once with the given ids, `applyDiscount` is called once with the percentage unchanged and the mocked unit of work, and `commitWork()` is verified once — with `startOrdering()`/`stopOrdering()` pinning that `applyDiscount` happens before `commitWork()`.
- **Boundaries**: `50` and `0.01` are asserted as valid, pinning the inclusive upper bound.

