        Id accId2 = fflib_IDGenerator.next(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accId1, accId2 };

        Id oppId1 = fflib_IDGenerator.next(Opportunity.SObjectType);
        Id oppId2 = fflib_IDGenerator.next(Opportunity.SObjectType);
        Id oppId3 = fflib_IDGenerator.next(Opportunity.SObjectType);
        Id oppId4 = fflib_IDGenerator.next(Opportunity.SObjectType);

        List<Opportunity> opps = new List<Opportunity>{
            new Opportunity(
                Id = oppId1,
                AccountId = accId1,
                StageName = 'Prospecting',
                Amount = 100000,
                Probability = 10
            ),
            new Opportunity(
                Id = oppId2,
                AccountId = accId1,
                StageName = 'Prospecting',
                Amount = 50000,
                Probability = 20
            ),
            new Opportunity(
                Id = oppId3,
                AccountId = accId2,
                StageName = 'Closed Won', // stage name is just a grouping key here
                Amount = 25000.555,
                Probability = 90
            ),
            // Ignored: null Amount
            new Opportunity(
                Id = oppId4,
                AccountId = accId2,
                StageName = 'Prospecting',
                Amount = null,
                Probability = 50
            )
        };

        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(opps);

