```javascript
import { LightningElement, api } from 'lwc';

const OPTION_PREFIX = 'statusListbox-option-';
const NAVIGATION_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];
    @api value = '';

    activeIndex = 0;

    get listId() {
        return 'statusListbox-list';
    }

    get activeDescendantId() {
        return OPTION_PREFIX + this.activeIndex;
    }

    connectedCallback() {
        this.activeIndex = this.computeActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue;
        this.activeIndex = this.computeActiveIndex();
    }

    computeActiveIndex() {
        const idx = this._options.findIndex(
            (option) => option.value === this._value
        );
        return idx >= 0 ? idx : 0;
    }

    @api
    get options() {
        return this._options;
    }

    set options(newOptions) {
        this._options = newOptions ? [...newOptions] : [];
        this.activeIndex = this.computeActiveIndex();
    }

    get displayOptions() {
        return this._options.map((option, index) => ({
            ...option,
            id: OPTION_PREFIX + index,
            selected: option.value === this._value
        }));
    }

    handleKeydown(event) {
        if (!NAVIGATION_KEYS.includes(event.key)) {
            return;
        }

        event.preventDefault();

        switch (event.key) {
            case 'ArrowDown':
                if (this.activeIndex < this._options.length - 1) {
                    this.activeIndex++;
                }
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    this.activeIndex--;
                }
                break;
            case 'Home':
                this.activeIndex = 0;
                break;
            case 'End':
                this.activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectIndex(this.activeIndex);
                break;
        }
    }

    handleClick(event) {
        const li = event.target.closest('li');
        if (!li) {
            return;
        }
        const index = Number(li.dataset.index);
        if (Number.isNaN(index)) {
            return;
        }
        this.activeIndex = index;
        this.selectIndex(index);
    }

    selectIndex(index) {
        const option = this._options[index];
        if (!option || option.value === this._value) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
