```apex
/**
 * Service that creates Enhanced Recurring Donations (npe03__Recurring_Donation__c)
 * for monthly giving sign-ups coming from the nonprofit's donation form.
 *
 * NPSP generates the installment Opportunities itself; this class only creates
 * the Recurring Donation records and never touches Opportunities.
 */
public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String INSTALLMENT_PERIOD_MONTHLY = 'Monthly';
    private static final String SCHEDULE_TYPE_FIXED = 'Fixed';
    private static final String SCHEDULE_TYPE_OPEN = 'Open';
    private static final String OPEN_ENDED_NONE = 'None';
    private static final Integer LAST_DAY_OF_MONTH = 29;

    /**
     * Creates one Enhanced Recurring Donation per request and returns the new
     * Ids in request order. Throws RecurringGiftException before any DML if
     * any request is invalid.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        validateAll(requests);

        List<npe03__Recurring_Donation__c> toInsert =
            new List<npe03__Recurring_Donation__c>(requests.size());

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
                npe03__Contact__c = req.contactId,
                npe03__Amount__c = req.amount,
                npe03__Installment_Period__c = INSTALLMENT_PERIOD_MONTHLY,
                npe03__Date_Established__c = req.startDate,
                npsp__RecurringType__c = 'Recurring',
                npsp__InstallmentFrequency__c = 1,
                npsp__StartDate__c = req.startDate,
                npsp__Status__c = 'Active',
                npsp__PaymentMethod__c = req.paymentMethod
            );

            Boolean fixedLength = req.installments != null && req.installments > 0;
            if (fixedLength) {
                rd.npsp__Schedule_Type__c = SCHEDULE_TYPE_FIXED;
                rd.npe03__Installments__c = req.installments;
            } else {
                rd.npsp__Schedule_Type__c = SCHEDULE_TYPE_OPEN;
                rd.npe03__Open_Ended_Status__c = OPEN_ENDED_NONE;
            }

            if (req.dayOfMonth == 31) {
                // Enhanced Recurring Donations' own "last day of the month" option
                rd.npsp__Day_of_Month__c = LAST_DAY_OF_MONTH;
                rd.npsp__Always_Use_Last_Day_Of_Month__c = true;
            } else {
                rd.npsp__Day_of_Month__c = req.dayOfMonth;
                rd.npsp__Always_Use_Last_Day_Of_Month__c = false;
            }

            toInsert.add(rd);
        }

        try {
            insert toInsert;
        } catch (DmlException e) {
            throw new RecurringGiftException(
                'Failed to create recurring donations: ' + e.getMessage(), e);
        }

        List<Id> result = new List<Id>(toInsert.size());
        for (npe03__Recurring_Donation__c rd : toInsert) {
            result.add(rd.Id);
        }
        return result;
    }

    /**
     * Validates every request up front so we never perform partial DML.
     */
    private static void validateAll(List<GiftRequest> requests) {
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];
            String prefix = 'Request ' + i + ': ';

            if (req == null) {
                throw new RecurringGiftException(prefix + 'request is null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException(prefix + 'contactId is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException(prefix + 'amount must be a positive number.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException(prefix + 'dayOfMonth must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException(prefix + 'startDate is required.');
            }
        }
    }
}
