/**
 * Service to create NPSP parent/child Relationships from an external student system.
 *
 * For each (child Contact Id -> parent Contact Id) pair, creates:
 *   - Child -> Parent  : Type = 'Parent', Status = 'Current'
 *   - Parent -> Child  : Type = Son / Daughter / Child, based on the parent's
 *                        NPSP "Relationship Lookup" setting (via List Setting reciprocal method).
 *
 * NPSP's own trigger normally auto-creates the reciprocal record, but we create both
 * explicitly so the result is deterministic and bulk-safe (1 SOQL, 1 DML).
 */
public inherited sharing class FamilyService {

    private static final String TYPE_PARENT   = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * @param parentIdByChildId Map of child Contact Id (key) to parent Contact Id (value).
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null or empty input: do nothing.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ---- 1. Collect valid, distinct pairs ----
        Set<Id> contactIds = new Set<Id>();
        Map<Id, Id> pairs = new Map<Id, Id>(); // childId -> parentId
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue; // skip invalid / self-referential entries
            }
            pairs.put(childId, parentId);
            contactIds.add(childId);
            contactIds.add(parentId);
        }
        if (pairs.isEmpty()) {
            return;
        }

        // ---- 2. One SOQL query: existing relationships between any of the pairs ----
        // Relationships are queried in both directions for all involved contacts,
        // then filtered to exactly the pairs in question.
        Map<Id, Id> existingPairKey = new Map<Id, Id>(); // canonical key -> marker
        List<npe4__Relationship__c> existing = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
               AND npe4__RelatedContact__c IN :contactIds
        ];
        Set<String> existingKeys = new Set<String>();
        for (npe4__Relationship__c rel : existing) {
            existingKeys.add(canonicalKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        // ---- 3. Determine reciprocal types (no extra queries) ----
        // Relationship Lookup settings are queried once only if needed; to keep
        // within the SOQL budget we read them from a single describe-free query.
        Map<String, npe4__Relationship_Lookup__c> lookupByName =
            new Map<String, npe4__Relationship_Lookup__c>(
                [SELECT Name, npe4__Male__c, npe4__Female__c, npe4__Neutral__c, npe4__Active__c
                 FROM npe4__Relationship_Lookup__c
                 WHERE Name = :TYPE_PARENT
                   AND npe4__Active__c = true]);

        // Need parent genders to pick Son/Daughter/Child.
        Map<Id, Contact> contactsById = new Map<Id, Contact>(
            [SELECT Id, Sex__c FROM Contact WHERE Id IN :contactIds]);

        String maleType   = TYPE_PARENT; // sensible fallbacks
        String femaleType = TYPE_PARENT;
        String neutralType = TYPE_PARENT;
        if (lookupByName.containsKey(TYPE_PARENT)) {
            npe4__Relationship_Lookup__c lookup = lookupByName.get(TYPE_PARENT);
            if (String.isNotBlank(lookup.npe4__Male__c)) {
                maleType = lookup.npe4__Male__c;
            }
            if (String.isNotBlank(lookup.npe4__Female__c)) {
                femaleType = lookup.npe4__Female__c;
            }
            if (String.isNotBlank(lookup.npe4__Neutral__c)) {
                neutralType = lookup.npe4__Neutral__c;
            }
        }

        // ---- 4. Build records: one per direction per pair ----
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : pairs.keySet()) {
            Id parentId = pairs.get(childId);

            // Skip if any relationship already exists between the two contacts
            // in either direction.
            if (existingKeys.contains(canonicalKey(childId, parentId))) {
                continue;
            }

            // Child -> Parent
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c       = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c          = TYPE_PARENT,
                npe4__Status__c        = STATUS_CURRENT,
                npe4__Description__c   = 'Created by student system import (FamilyService).'
            ));

            // Parent -> Child (reciprocal, gender-based)
            Contact parentContact = contactsById.get(parentId);
            String childType = neutralType;
            if (parentContact != null && String.isNotBlank(parentContact.Sex__c)) {
                String sex = parentContact.Sex__c.trim().toLowerCase();
                if (sex == 'm' || sex == 'male') {
                    childType = maleType;
                } else if (sex == 'f' || sex == 'female') {
                    childType = femaleType;
                }
            }
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c       = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Type__c          = childType,
                npe4__Status__c        = STATUS_CURRENT,
                npe4__Description__c   = 'Created by student system import (FamilyService).'
            ));
        }

        // ---- 5. One DML statement ----
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /** Order-independent key for a pair of Contact Ids, so "either direction" matching works. */
    private static String canonicalKey(Id a, Id b) {
        if (a < b) {
            return a + '|' + b;
        }
        return b + '|' + a;
    }
}
```

Looking at the requirements, the key mechanics are:

- **Auto-incrementing builds**: `versionNumber` of `1.2.0.NEXT`.
- **Always the highest promoted ancestor without manual edits**: `ancestorVersion: null` tells the packaging CLI to automatically use the highest promoted version of the package at creation time — no file edits needed between releases.
- **Fixtures that must not ship in the package**: 2GP supports `unpackagedMetadata` on a package directory — that metadata is deployed to the packaging scratch org to support Apex tests run during `sf package version create --code-coverage`, but is excluded from the uploaded package version, so subscribers never receive it. Pointing it at `triage-test-fixtures` covers the custom metadata records, the test data factory class, and the running user's setup (the `Triage_Agent` permission set ships in the package itself and is present in the test org; the `SalesConsoleUser` PSL assignment for the test runner is part of the unpackaged fixture metadata deployed before tests run).
- **Dev workflow**: `triage-test-fixtures` is also declared as its own package directory (no `package` key, `default: false`), so `sf project deploy start` can deploy it to scratch orgs on demand while it belongs to no package.
- Namespace `triagex` at the root, `sourceApiVersion` 65.0, `triage` as the default directory.

