/**
 * Trigger Action (TAF): creates an onboarding Task for the account owner
 * when a new Account of type "Customer - Direct" or "Customer - Channel" is inserted.
 */
public inherited sharing class TA_Account_CreateOnboardingTask
        implements TriggerAction.AfterInsert {

    private static final String ONBOARDING_SUBJECT = 'Onboard new customer';
    private static final Set<String> CUSTOMER_TYPES =
        new Set<String>{'Customer - Direct', 'Customer - Channel'};

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> tasks = new List<Task>();
        for (SObject sobj : triggerNew) {
            Account acc = (Account) sobj;
            if (acc.Type != null && CUSTOMER_TYPES.contains(acc.Type)) {
                tasks.add(
                    new Task(
                        Subject = ONBOARDING_SUBJECT,
                        WhatId = acc.Id,
                        OwnerId = acc.OwnerId,
                        ActivityDate = Date.today().addDays(7),
                        Status = 'Not Started',
                        Priority = 'Normal'
                    )
                );
            }
        }
        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
