/**
 * Trigger Action (TAF) for Opportunity: collects the Ids of opportunities
 * that must be pushed to the ERP (created, or updated with a StageName change).
 *
 * Records are accumulated in transaction-scoped static state so that a single
 * DML operation chunked by the trigger (e.g. 200 + 50) still yields exactly
 * one set of Ids, which the DML finalizer enqueues as one Queueable job.
 */
public inherited sharing class TA_Opportunity_CollectForErpSync
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    /** Transaction-wide accumulator: one entry per opportunity needing ERP sync. */
    @TestVisible
    private static Set<Id> opportunityIdsToSync = new Set<Id>();

    /** Ids pending sync for the current transaction; consumed by the finalizer. */
    public static Set<Id> getPendingSyncIds() {
        return opportunityIdsToSync;
    }

    /** Removes the pending Ids; called by the finalizer once the job is enqueued. */
    public static void clearPendingSyncIds() {
        opportunityIdsToSync = new Set<Id>();
    }

    public void afterInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            opportunityIdsToSync.add(record.Id);
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = (Opportunity) triggerNew[i];
            Opportunity oldOpp = (Opportunity) triggerOld[i];
            if (newOpp.StageName != oldOpp.StageName) {
                opportunityIdsToSync.add(newOpp.Id);
            }
        }
    }
}
