```apex
/**
 * TAF DML Finalizer: runs once at the end of every DML operation handled by
 * the framework, for any sObject. It enqueues exactly one
 * OpportunityErpSyncJob per DML operation, containing the Ids of all
 * opportunities from that operation that need ERP sync (accumulated across
 * trigger chunks by TA_Opportunity_CollectForErpSync), and no job at all
 * when there are none. It performs no DML.
 */
public inherited sharing class OpportunityErpSyncFinalizer
        implements TriggerAction.DmlFinalizer {

    public void execute(FinalizerHandler.Context context) {
        Set<Id> pendingIds = TA_Opportunity_CollectForErpSync.getPendingSyncIds();

        // Only enqueue for opportunities actually pending sync; this finalizer
        // is invoked for every sObject's DML operations, so other objects (or
        // DML operations that changed nothing relevant) produce no job.
        Boolean hasOpportunities = false;
        for (Id recordId : pendingIds) {
            if (String.valueOf(recordId).startsWith(Opportunity.SObjectType.getDescribe().getKeyPrefix())) {
                hasOpportunities = true;
                break;
            }
        }
        if (!hasOpportunities) {
            return;
        }

        System.enqueueJob(new OpportunityErpSyncJob(pendingIds));
        TA_Opportunity_CollectForErpSync.clearPendingSyncIds();
    }
}
